package app;
import java.time.*;
class Module1 {
    static void menu(){
        while(true){System.out.println("\n--- MODULE 1: HOTELS & ROOMS ---\n1 Add hotel\n2 Add room\n3 View hotels/rooms\n4 Update room\n5 Add maintenance\n6 Remove maintenance\n7 Delete hotel\n0 Back");int ch=Data.number("Choice: ");if(ch==0)return;
            if(ch==1)addHotel();else if(ch==2)addRoom();else if(ch==3)view();else if(ch==4)update();else if(ch==5)maintenance();else if(ch==6)removeMaintenance();else if(ch==7)delete();else System.out.println("Invalid choice");
        }
    }
    static boolean allowed(){String role=Data.ask("Role (Admin/Manager/Guest): ");if(role.equalsIgnoreCase("Admin")||role.equalsIgnoreCase("Manager"))return true;System.out.println("Only Admin or Manager allowed.");return false;}
    static void addHotel(){if(!allowed())return;String n=Data.ask("Hotel name: "),c=Data.ask("City: "),a=Data.ask("Address: ");int s=Data.number("Stars (1-5): ");if(n.isEmpty()||c.isEmpty()||a.isEmpty()||s<1||s>5){System.out.println("Invalid hotel details.");return;}Hotel h=new Hotel(Data.hotelId++,n,c,a,s);Data.hotels.add(h);System.out.println("Hotel added (ID "+h.id+"). Add at least one room now.");addRoomTo(h.id);}
    static void addRoom(){if(!allowed())return;addRoomTo(Data.number("Hotel ID: "));}
    static void addRoomTo(int id){Hotel h=Data.hotel(id);if(h==null){System.out.println("Hotel not found.");return;}String n=Data.ask("Room number: ");for(Room r:Data.rooms)if(r.hotelId==id&&r.number.equalsIgnoreCase(n)){System.out.println("Room number already used in this hotel.");return;}String t=Data.ask("Type (Single/Double/Deluxe/Suite): ");int c=Data.number("Guest capacity: ");double p=Data.money("Price per night: ");if(n.isEmpty()||!(t.equalsIgnoreCase("Single")||t.equalsIgnoreCase("Double")||t.equalsIgnoreCase("Deluxe")||t.equalsIgnoreCase("Suite"))||c<1||p<=0){System.out.println("Invalid room details.");return;}Room r=new Room(Data.roomId++,id,n,t,c,p);Data.rooms.add(r);System.out.println("Room added ID: "+r.id);}
    static void view(){for(Hotel h:Data.hotels){System.out.println("Hotel "+h.id+": "+h.name+" | "+h.city+" | "+h.address+" | "+h.stars+" stars");for(Room r:Data.rooms)if(r.hotelId==h.id)System.out.println("  Room ID "+r.id+" | No "+r.number+" | "+r.type+" | Capacity "+r.capacity+" | Rs "+r.price);}}
    static void update(){if(!allowed())return;Room r=Data.room(Data.number("Room ID: "));if(r==null){System.out.println("Room not found");return;}boolean ever=false;for(Booking b:Data.bookings)if(b.roomIds.contains(r.id)){ever=true;break;}System.out.println("1 Number\n2 Type\n3 Capacity\n4 Price");int c=Data.number("Choice: ");if((c==1||c==2)&&ever){System.out.println("Cannot change number/type after a booking exists.");return;}if(c==1){String n=Data.ask("New room number: ");if(n.isEmpty())return;for(Room other:Data.rooms)if(other!=r&&other.hotelId==r.hotelId&&other.number.equalsIgnoreCase(n)){System.out.println("Duplicate room number");return;}r.number=n;}else if(c==2){String t=Data.ask("New type: ");if(!(t.equalsIgnoreCase("Single")||t.equalsIgnoreCase("Double")||t.equalsIgnoreCase("Deluxe")||t.equalsIgnoreCase("Suite"))){System.out.println("Invalid type");return;}r.type=t;}else if(c==3){int n=Data.number("Capacity: ");if(n<1)return;r.capacity=n;}else if(c==4){double p=Data.money("Price: ");if(p<=0)return;r.price=p;}else return;System.out.println("Updated.");}
    static void maintenance(){if(!allowed())return;Room r=Data.room(Data.number("Room ID: "));if(r==null)return;LocalDate a=Data.date("Start"),b=Data.date("End (exclusive)");if(!b.isAfter(a)||a.isBefore(LocalDate.now())){System.out.println("Invalid dates");return;}for(Booking bk:Data.bookings)if(bk.roomIds.contains(r.id)&&(bk.status.equals("Confirmed")||bk.status.equals("Checked In"))&&Data.overlap(a,b,bk.in,bk.out)){System.out.println("Existing booking conflicts.");return;}r.maintenance.add(new DateBlock(a,b));System.out.println("Maintenance added.");}
    static void removeMaintenance(){if(!allowed())return;Room r=Data.room(Data.number("Room ID: "));if(r==null)return;for(int i=0;i<r.maintenance.size();i++){DateBlock b=r.maintenance.get(i);System.out.println((i+1)+". "+b.start+" to "+b.end);}int n=Data.number("Block number to remove: ");if(n>=1&&n<=r.maintenance.size()){r.maintenance.remove(n-1);System.out.println("Removed.");}}
    static void delete(){if(!allowed())return;int id=Data.number("Hotel ID: ");Hotel h=Data.hotel(id);if(h==null)return;for(Booking b:Data.bookings)if(b.hotelId==id&&b.in.isAfter(LocalDate.now())&&!b.status.equals("Cancelled")&&!b.status.equals("No Show")){System.out.println("Cannot delete: upcoming booking.");return;}Data.hotels.remove(h);Data.rooms.removeIf(r->r.hotelId==id);System.out.println("Hotel deleted.");}
}
